"""Generate an offline, searchable inspection gallery from Godot render sheets."""
from forge_rebuild import ROOT,OUT,atomic
import json,html
folder=ROOT/'docs/forge_rebuild';plan=json.loads((OUT/'plan.json').read_text())
categories={'mob':'Creatures','hero':'Rider','horse':'Rider','environment':'World','npc':'Residents','weapon':'Equipment'}
known={'res://'+e['target'].removeprefix('game/'):categories[e['category']] for e in plan['assets']}
sheets=[]
for pattern in ['gallery_idle_*.json','legacy_idle_*.json','residents_idle_*.json','gallery_run_*.json','gallery_attack_01_*.json']:
 for path in sorted(folder.glob(pattern)):
  data=json.loads(path.read_text());image=path.with_suffix('.png')
  if not image.exists():continue
  tags=sorted(set(known.get(x['path'],'Residents' if '/npcs/' in x['path'] else 'Legacy') for x in data['assets']))
  if data.get('clip','idle')!='idle':tags.append('Animation')
  sheets.append({'image':image.name,'names':[x['name'] for x in data['assets']],'tags':tags,'clip':data.get('clip','idle')})
asset_count=len({x['path'] for pattern in ['gallery_idle_*.json','legacy_idle_*.json','residents_idle_*.json'] for p in folder.glob(pattern) for x in json.loads(p.read_text())['assets']})
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ironfield · Forge model review</title>
<style>body{margin:0;background:#161c1c;color:#e8e6dd;font:16px system-ui}header,main{max-width:1200px;margin:auto;padding:30px}h1{font-size:clamp(28px,4vw,48px);margin:5px 0}p{color:#bbbfb7;line-height:1.6}a{color:#d9bb77}.metrics{display:flex;gap:35px;margin:24px 0}.metrics strong{display:block;color:#d9bb77;font-size:30px}nav{display:flex;flex-wrap:wrap;gap:8px}button,input{background:#263130;color:#eee;border:1px solid #465451;padding:10px 16px;border-radius:6px;font:inherit}button{cursor:pointer}button[aria-pressed=true]{background:#56694e}input{margin:16px 0;width:min(90%,500px)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,460px),1fr));gap:22px}article{background:#222b2a;border:1px solid #3b4642;border-radius:10px;overflow:hidden}article img{width:100%;display:block}article div{padding:15px}article p{margin:8px 0;font-size:14px}.small{font-size:14px}footer{padding:30px;border-top:1px solid #3b4642}#count{margin-left:12px;color:#bfc6b8}</style>
<header><p>IRONFIELD / LOCAL ASSET FORGE</p><h1>Concepts brought into Godot</h1><p>Actual imported models, photographed from the front, side, and three-quarter view. Click a sheet for the full image. Equipment is stood upright on this review stage; its gameplay socket orientation is preserved.</p><div class="metrics"><div><strong>59</strong>original models replaced</div><div><strong>37</strong>creature variants</div><div><strong>10</strong>residents</div></div><p class="small">These are playable neural reconstructions. Faces, hands, fine foliage and complex limb surfaces retain reconstruction artifacts. Related weapons, scenery and residents share reconstructed base geometry. The report records both the corrections and the remaining art limitations.</p><p><a href="README.md">Build report</a> · <a href="inventory_validation.json">Model audit</a> · <a href="forge_export_receipts.json">Generator provenance</a> · <a href="../screenshots/horse-reference/godot/forge_rebuild/mounted_threequarter.png">Mounted rider</a></p></header>
<main><nav id="filters"></nav><input id="search" aria-label="Search model names" placeholder="Find a creature, resident, prop or weapon"><span id="count"></span><div id="grid" class="grid"></div></main>
<footer>Captured inside Godot 4.7.2 with the Compatibility renderer. Agent visual inspection is separate from the generator’s human acceptance status.</footer>
<script>const sheets=__SHEETS__;let active='All';const filters=document.querySelector('#filters'),grid=document.querySelector('#grid'),search=document.querySelector('#search');
for(const label of ['All','Creatures','Rider','World','Residents','Equipment','Legacy','Animation']){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-pressed',label===active);b.onclick=()=>{active=label;for(const child of filters.children)child.setAttribute('aria-pressed',child===b);draw()};filters.append(b)}
function draw(){grid.replaceChildren();const query=search.value.toLowerCase();const visible=sheets.filter(s=>(active==='All'||s.tags.includes(active))&&s.names.join(' ').toLowerCase().includes(query));document.querySelector('#count').textContent=visible.length+' sheets';for(const s of visible){const article=document.createElement('article'),link=document.createElement('a'),img=document.createElement('img'),text=document.createElement('div'),title=document.createElement('strong'),caption=document.createElement('p');link.href=s.image;link.target='_blank';img.src=s.image;img.loading='lazy';img.alt=s.names.join(', ')+' — front, side and three-quarter';link.append(img);title.textContent=s.names.join(' · ');caption.textContent=s.tags.join(' / ')+' · '+s.clip;text.append(title,caption);article.append(link,text);grid.append(article)}}search.oninput=draw;draw();</script></html>'''.replace('__SHEETS__',json.dumps(sheets).replace('</','<\\/'))
page=page.replace('</header>', '<p class="small">In-game captures: <a href="world_review/townfolk_crossing.png">Settlement</a> &middot; <a href="world_review/townfolk_wilderness.png">Wilderness</a> &middot; <a href="world_review/mounted_cut0_frame15.png">Mounted sword attack</a> &middot; <a href="world_review/hero_face.png">Face detail</a> &middot; <a href="visual_review.json">Inspection record</a></p></header>')
(folder/'gallery.html').write_text(page,encoding='utf-8')
atomic(folder/'gallery_index.json',{'unique_runtime_models':asset_count,'sheet_count':len(sheets),'sheets':sheets})
print('Offline gallery:',asset_count,'models;',len(sheets),'sheets.')
